"""Build a review of unmodified Godot framebuffer captures; no art generation."""
from pathlib import Path
import html, json
root = Path(__file__).resolve().parents[1]
art = root / 'artifacts'
results = {key: json.loads((art/f'quests39_{key}.json').read_text()) for key in ['mechanics','native','regression']}
views = [
('forest','Vạn Thú Sơn có người giữ trại','Lâm An dưới mái che, Yên Chi ở góc dược liệu. Biển chỉ lối dẫn về cổ trận.'),
('mentor_dialogue','Một cuộc trò chuyện để bắt đầu','Bấm NPC hoặc lại gần nhấn E. Chọn câu hỏi, xem nhiệm vụ hoặc tạm biệt.'),
('quest_accepted','Nhận nhiệm vụ đầu tiên','Lời dặn dưới đèn dẫn tới Yên Chi. HUD theo dõi mục tiêu và người cần gặp.'),
('herbalist_dialogue','Yên Chi • dược sư của trại','Lời thoại hướng dẫn thức ăn của từng Cổ và cách thu phục.'),
('quest_reward','Trở lại báo tin','Trả đúng NPC mới nhận thưởng. Nhiệm vụ tiếp theo mở sau khi hoàn thành.'),
('journal','Nhật ký nhiệm vụ','F11 xem tiến độ, phần thưởng, điều kiện mở và dẫn đường tới người cần gặp.'),
('ruins','Thẩm Nghi ở Tàn Tích','Bàn khảo cổ và cờ cổ trận tạo mốc cho chặng mở bí cảnh.'),
('ruins_dialogue','Dấu ấn thất lạc','Thu cổ tinh, phục hồi cổ trận và đem lời nhắn đến Mộc Miên trong Thanh Nang.'),
('realm','Thanh Nang • vụ mùa đầu','Ao sen có va chạm, góc nông cụ và người chăm linh điền bên sáu luống đất.'),
('gardener_dialogue','Mộc Miên • người chăm linh điền','Hai nhiệm vụ cuối nối gieo trồng, chăn nuôi, thu tài nguyên và nâng cấp Cổ.'),
('dialogue_960','Hội thoại ở 960 × 640','Chân dung, lời thoại và lựa chọn nằm trong màn hình; phần dài cuộn dọc.'),
('journal_960','Nhật ký ở 960 × 640','Danh sách cuộn dọc; không tràn chiều ngang.'),
('reduced_motion','Giảm chuyển động','Dừng cử chỉ và chuyển động trang trí; lời thoại hiện trọn ngay lập tức.')]
figures = ''.join(f'<figure><img loading="lazy" src="quests39_{key}.png" alt="{html.escape(title)}"><figcaption><h2>{html.escape(title)}</h2><p>{html.escape(body)}</p></figcaption></figure>' for key,title,body in views)
stats = ' · '.join(f'{r["passed"]}/{r["passed"] + r["failed"]} {label}' for key,label in [('mechanics','cơ chế'),('native','native'),('regression','hồi quy')] for r in [results[key]])
page = '''<!doctype html><html lang="vi"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Người giữ trại — Cổ giới 0.39</title><style>
*{box-sizing:border-box}body{margin:0;background:#20291f;color:#efdfbc;font:17px/1.6 system-ui,sans-serif}main{max-width:1280px;margin:auto;padding:42px 28px}header{max-width:870px;margin-bottom:28px}.eyebrow{color:#b2c398;font-size:12px;letter-spacing:.16em}h1{font:clamp(32px,4.2vw,56px)/1.12 Georgia,serif;margin:14px 0 20px}h2{font-size:20px;margin:0}p{color:#c5c9b5;margin:10px 0}nav,.controls{display:flex;gap:10px;align-items:center;flex-wrap:wrap;margin:20px 0}button,a{font:inherit;color:inherit;background:#344631;padding:8px 16px;border:1px solid #718464;border-radius:3px;cursor:pointer;text-decoration:none}button:hover,a:hover,button[aria-pressed=true]{background:#4c6243}kbd{background:#ead9b4;color:#293125;padding:2px 6px;border-radius:2px}.stats{font-size:14px;color:#b5c997;margin-top:20px}.gallery[hidden]{display:none}figure{margin:0 0 28px;border:1px solid #526148;background:#293526}img{display:block;width:100%;height:auto}figcaption{padding:20px 24px}figcaption p{font-size:15px;margin:5px 0}input{accent-color:#b7c693;flex:1;min-width:160px}footer{margin-top:30px;border-top:1px solid #536749;padding-top:22px;font-size:14px}.controls output{min-width:80px}@media(max-width:600px){main{padding:26px 12px}figcaption{padding:16px}nav a,nav button{font-size:14px}} 
</style></head><body><main><header><div class="eyebrow">GU MASTER 2D / BẢN PHÁT TRIỂN 0.39</div><h1>Người giữ trại.<br>Một hành trình có lời dẫn.</h1><p>Bốn NPC, sáu nhiệm vụ nhập môn và những góc sinh hoạt trong ba vùng. Ảnh và chuỗi chuyển động dưới đây chụp trực tiếp từ Godot PC.</p><p><kbd>E</kbd> Trò chuyện · <kbd>F11</kbd> Nhật ký · <kbd>Esc</kbd> Tạm biệt<br><kbd>WASD</kbd> Di chuyển · <kbd>1–4</kbd> Dùng Cổ · <kbd>T</kbd> Địa đồ</p><div class="stats">STATS</div></header><nav><button data-tab="gallery" aria-pressed="true">Nhiệm vụ & môi trường</button><button data-tab="motion" aria-pressed="false">Cử chỉ NPC</button><a href="quests39_native.json">Kiểm tra native</a><a href="quests39_mechanics.json">Cơ chế & lưu</a></nav><section id="gallery" class="gallery">FIGURES</section><section id="motion" class="gallery" hidden><h2>Lâm An • cử chỉ khi trò chuyện</h2><p>24 khung hình runtime. Dùng thanh kéo để xem từng tư thế, hoặc phát chậm để quan sát tay, đầu và điểm đứng.</p><div class="controls"><button id="play" aria-pressed="false">Phát chậm</button><button id="prev" aria-label="Khung trước">←</button><button id="next" aria-label="Khung sau">→</button><input id="seek" type="range" min="0" max="23" value="0" aria-label="Khung hình NPC"><output id="frame">01 / 24</output></div><figure><img id="motion-image" src="quests39_talk_00.png" alt="Cử chỉ Lâm An trong Godot"><figcaption><h2>Khớp cử động, điểm đứng giữ ổn định</h2><p>Ẩn HUD trong lúc chụp để thấy toàn bộ nhân vật. Dùng rig hiện hành; chân dung hội thoại và NPC cùng diện mạo. Chuỗi xem chậm không dùng để đo FPS.</p></figcaption></figure></section><footer><strong>Chơi từ đâu?</strong><p>Gặp Lâm An → làm quen Yên Chi → giữ lối về trại / cho Cổ ăn → gặp Thẩm Nghi ở Tàn Tích → phục hồi Thanh Nang → gặp Mộc Miên → vụ mùa đầu và chăn nuôi–nâng Cổ.</p><p>Tiến độ lưu cùng hồ sơ, hỗ trợ hồ sơ cũ và chống nhận thưởng lặp. Kiểm thử native có dùng fixture để bỏ qua thời gian chiến đấu và mở vùng ở chặng sau; chuỗi cơ chế kiểm riêng. Chưa có lồng tiếng, lịch sinh hoạt NPC hay kiểm cân bằng dài hạn. Game hiện vẫn là prototype PC chơi đơn.</p></footer></main><script>
const seek=document.querySelector('#seek'),frame=document.querySelector('#frame'),actor=document.querySelector('#motion-image'),play=document.querySelector('#play');let playing=false,timer;const frames=Array.from({length:24},(_,i)=>`quests39_talk_${String(i).padStart(2,'0')}.png`);window.npcFrames=frames;
function show(n){seek.value=(n+24)%24;actor.src=frames[+seek.value];frame.textContent=`${String(+seek.value+1).padStart(2,'0')} / 24`}
function stop(){playing=false;clearInterval(timer);play.textContent='Phát chậm';play.setAttribute('aria-pressed','false')}
play.onclick=()=>{if(playing)return stop();playing=true;play.textContent='Dừng';play.setAttribute('aria-pressed','true');timer=setInterval(()=>show(+seek.value+1),220)};seek.oninput=()=>{stop();show(+seek.value)};document.querySelector('#prev').onclick=()=>{stop();show(+seek.value-1)};document.querySelector('#next').onclick=()=>{stop();show(+seek.value+1)};
document.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>{stop();document.querySelectorAll('.gallery').forEach(s=>s.hidden=s.id!==b.dataset.tab);document.querySelectorAll('[data-tab]').forEach(t=>t.setAttribute('aria-pressed',String(t===b)))});document.addEventListener('visibilitychange',()=>{if(document.hidden)stop()});
</script></body></html>'''
(art/'quests39_review.html').write_text(page.replace('STATS',stats).replace('FIGURES',figures),encoding='utf-8')
print('Built quests39_review.html: 13 stills + 24 native motion frames')
